class I18n(QObject):
    changed=Signal()
    def __init__(self,app,language='en'):
        super().__init__();self.app=app;self.language='en';self.qt=QTranslator(self);self.missing=set();self.set_language(language,emit=False)
    def text(self,key,**values):
        if key not in DE:self.missing.add(key)
        return (DE.get(key,key) if self.language=='de' else key).format(**values)
    def error(self,message):
        if self.language!='de':return message
        prefix='F0 rejected command: '
        if message.startswith(prefix):return DE[prefix]+self.error(message[len(prefix):])
        if message in DE:return DE[message]
        for key in sorted(DE,key=len,reverse=True):
            if message.startswith(key):return DE[key]+message[len(key):]
        return message # OS/driver details retain their original technical text.
    def set_language(self,language,emit=True):
        if language not in ('en','de'):language='en'
        self.app.removeTranslator(self.qt);self.language=language
        if language=='de':
            if self.qt.load('qtbase_de',QLibraryInfo.path(QLibraryInfo.LibraryPath.TranslationsPath)):self.app.installTranslator(self.qt)
        if emit:self.changed.emit()
